import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.Stack;

public class BalancedParentheses {

    static class BracketMatcher {
        private final Map<Character, Character> openerToCloser;
        private final Set<Character> closers;

        BracketMatcher(Map<Character, Character> openerToCloser) {
            this.openerToCloser = openerToCloser;
            this.closers = new HashSet<>(openerToCloser.values());
        }

        boolean isOpener(char c) {
            return openerToCloser.containsKey(c);
        }

        boolean isCloser(char c) {
            return closers.contains(c);
        }

        boolean matches(char opener, char closer) {
            return closer == openerToCloser.getOrDefault(opener, '\0');
        }
    }

    private static final Map<Character, Character> DEFAULT_PAIRS = Map.of(
        '(', ')',
        '{', '}',
        '[', ']'
    );

    public static boolean isBalanced(String s) {
        return isBalanced(s, DEFAULT_PAIRS);
    }

    public static boolean isBalanced(String s, Map<Character, Character> pairs) {
        BracketMatcher matcher = new BracketMatcher(pairs);
        Stack<Character> st = new Stack<>();
        for (char c : s.toCharArray()) {
            if (matcher.isOpener(c)) {
                st.push(c);
            } else if (matcher.isCloser(c)) {
                if (st.isEmpty()) return false;
                if (!matcher.matches(st.peek(), c)) return false;
                st.pop();
            }
        }
        return st.isEmpty();
    }

    public static void main(String[] args) {
        String s = "[()()]{}";
        System.out.println((isBalanced(s) ? "true" : "false"));
    }
}

